import { transformAsync } from '@babel/core';
import { posix } from 'node:path';
import { dependencyBannerTitle } from '../../../build/library.mjs';

/**
 * Preserve the ES5 syntax contract of the historical UMD browser bundles.
 *
 * Babel runs on modules before Rolldown creates the UMD wrapper. This keeps
 * Babel helpers inside the bundle factory and lets Vite run Terser afterwards.
 * A small final pass handles ES2015 syntax generated by Vite/Rolldown itself.
 *
 * @param {{enabled?: boolean, compact?: boolean, sourceMaps?: boolean, banner?: (chunk: {moduleIds: string[]}) => string}} [options]
 */
export function legacyUmdPlugin({ enabled = true, compact = true, sourceMaps = false, banner } = {}) {
  return {
    name: 'cherry-legacy-umd',
    async transform(code, id) {
      if (!enabled || !/\.[cm]?js(?:\?|$)/.test(id)) {
        return null;
      }
      const transformed = await transformAsync(code, {
        babelrc: false,
        configFile: false,
        comments: false,
        filename: id.split('?')[0],
        sourceMaps: true,
        presets: [
          [
            '@babel/preset-env',
            {
              bugfixes: true,
              modules: false,
              targets: { ie: '11' },
            },
          ],
        ],
      });

      return transformed?.code ? { code: transformed.code, map: transformed.map } : null;
    },
    generateBundle: {
      order: 'post',
      async handler(outputOptions, bundle) {
        if (!enabled || outputOptions.format !== 'umd') {
          return;
        }

        for (const output of Object.values(bundle)) {
          if (output.type !== 'chunk') {
            continue;
          }

          const header = banner?.(output);
          const transformed = await transformAsync(output.code, {
            babelrc: false,
            configFile: false,
            shouldPrintComment: (comment) => comment.startsWith(dependencyBannerTitle),
            compact,
            inputSourceMap: sourceMaps ? output.map || undefined : undefined,
            sourceMaps,
            plugins: [
              '@babel/plugin-transform-arrow-functions',
              '@babel/plugin-transform-shorthand-properties',
              '@babel/plugin-transform-template-literals',
              ({ types }) => ({
                visitor: {
                  Program: {
                    exit(path) {
                      // Terser can inline the UMD wrapper and hoist its local
                      // variables into the script scope. Restore isolation after
                      // minification while retaining the wrapper's original this.
                      if (path.node.body.some((node) => types.isDeclaration(node))) {
                        const wrapper = types.functionExpression(null, [], types.blockStatement(path.node.body));
                        path.node.body = [
                          types.expressionStatement(
                            types.callExpression(types.memberExpression(wrapper, types.identifier('call')), [
                              types.thisExpression(),
                            ]),
                          ),
                        ];
                      }
                      if (header && path.node.body[0]) {
                        types.addComment(path.node.body[0], 'leading', header.slice(2, -2));
                      }
                    },
                  },
                },
              }),
            ],
          });

          if (transformed?.code) {
            const mapFileName = output.sourcemapFileName || `${output.fileName}.map`;
            output.code = sourceMaps
              ? `${transformed.code}\n//# sourceMappingURL=${posix.relative(posix.dirname(output.fileName), mapFileName)}`
              : transformed.code;
            // generateBundle runs after the source map asset has been emitted.
            // Updating the chunk metadata alone leaves the published map stale.
            if (sourceMaps && transformed.map) {
              transformed.map.file = output.map?.file || posix.basename(output.fileName);
              const mapAsset = bundle[mapFileName];
              if (mapAsset?.type === 'asset') mapAsset.source = JSON.stringify(transformed.map);
            }
            output.map = sourceMaps ? transformed.map : null;
          }
        }
      },
    },
  };
}
